def makeGood(s: str) -> str:
    stack = []
    for c in s:
        if stack and abs(ord(stack[-1]) - ord(c)) == 32:
            # Current and previous form a bad pair (same letter, different case)
            stack.pop()
        else:
            stack.append(c)
    return ''.join(stack)
